window.ScripturaLexicons.BDAG_PART_0141 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-episitismos-bdag\" data-source=\"BDAG\" data-search=\"ἐπισιτισμός, οῦ, ὁ episitismós substantivo masculino provisões; mantimentos; abastecimento alimentar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπισιτισμός, οῦ, ὁ</td><td>substantivo masculino</td><td>provisões; mantimentos; abastecimento alimentar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-episkeptomai-bdag\" data-source=\"BDAG\" data-search=\"ἐπισκέπτομαι episképtomai verbo; depoente médio examinar; visitar; cuidar; assistir; socorrer BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπισκέπτομαι</td><td>verbo; depoente médio</td><td>examinar; visitar; cuidar; assistir; socorrer</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-episkeuazomai-bdag\" data-source=\"BDAG\" data-search=\"ἐπισκευάζομαι episkeuázomai verbo; médio preparar-se; aprontar-se BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπισκευάζομαι</td><td>verbo; médio</td><td>preparar-se; aprontar-se</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-episkenoo-bdag\" data-source=\"BDAG\" data-search=\"ἐπισκηνόω episkēnóō verbo estabelecer-se; alojar-se; habitar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπισκηνόω</td><td>verbo</td><td>estabelecer-se; alojar-se; habitar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-episkiazo-bdag\" data-source=\"BDAG\" data-search=\"ἐπισκιάζω episkiázō verbo projetar sombra; cobrir; envolver com sombra BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπισκιάζω</td><td>verbo</td><td>projetar sombra; cobrir; envolver com sombra</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-episkopeo-bdag\" data-source=\"BDAG\" data-search=\"ἐπισκοπέω episkopéō verbo observar atentamente; supervisionar; velar por BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπισκοπέω</td><td>verbo</td><td>observar atentamente; supervisionar; velar por</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-episkope-bdag\" data-source=\"BDAG\" data-search=\"ἐπισκοπή, ῆς, ἡ episkopḗ substantivo feminino visitação; cuidado; responsabilidade; supervisão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπισκοπή, ῆς, ἡ</td><td>substantivo feminino</td><td>visitação; cuidado; responsabilidade; supervisão</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-episkopos-bdag\" data-source=\"BDAG\" data-search=\"ἐπίσκοπος, ου, ὁ epískopos substantivo masculino guardião; supervisor; responsável pela supervisão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπίσκοπος, ου, ὁ</td><td>substantivo masculino</td><td>guardião; supervisor; responsável pela supervisão</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-episkoteo-bdag\" data-source=\"BDAG\" data-search=\"ἐπισκοτέω episkotéō verbo obscurecer; impedir de enxergar; encobrir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπισκοτέω</td><td>verbo</td><td>obscurecer; impedir de enxergar; encobrir</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epispao-bdag\" data-source=\"BDAG\" data-search=\"ἐπισπάω epispáō verbo; voz média atrair para si; trazer sobre si; recompor o prepúcio BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπισπάω</td><td>verbo; voz média</td><td>atrair para si; trazer sobre si; recompor o prepúcio</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epispeiro-bdag\" data-source=\"BDAG\" data-search=\"ἐπισπείρω epispeírō verbo semear por cima; semear posteriormente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπισπείρω</td><td>verbo</td><td>semear por cima; semear posteriormente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epispoudazo-bdag\" data-source=\"BDAG\" data-search=\"ἐπισπουδάζω epispoudázō verbo mostrar ainda mais zelo; esforçar-se adicionalmente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπισπουδάζω</td><td>verbo</td><td>mostrar ainda mais zelo; esforçar-se adicionalmente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epistamai-bdag\" data-source=\"BDAG\" data-search=\"ἐπίσταμαι epístamai verbo; depoente passivo compreender; saber; conhecer; estar informado BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπίσταμαι</td><td>verbo; depoente passivo</td><td>compreender; saber; conhecer; estar informado</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epistas-bdag\" data-source=\"BDAG\" data-search=\"ἐπιστάς epistás forma verbal; remissão ver ἐφίστημι BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπιστάς</td><td>forma verbal; remissão</td><td>ver ἐφίστημι</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epistasis-bdag\" data-source=\"BDAG\" data-search=\"ἐπίστασις, εως, ἡ epístasis substantivo feminino pressão; responsabilidade; cuidado; interrupção BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπίστασις, εως, ἡ</td><td>substantivo feminino</td><td>pressão; responsabilidade; cuidado; interrupção</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epistates-bdag\" data-source=\"BDAG\" data-search=\"ἐπιστάτης, ου, ὁ epistátēs substantivo masculino mestre; supervisor; responsável BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπιστάτης, ου, ὁ</td><td>substantivo masculino</td><td>mestre; supervisor; responsável</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epistello-bdag\" data-source=\"BDAG\" data-search=\"ἐπιστέλλω epistéllō verbo escrever; enviar instruções por carta BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπιστέλλω</td><td>verbo</td><td>escrever; enviar instruções por carta</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epistei-epistethi-bdag\" data-source=\"BDAG\" data-search=\"ἐπιστῇ, ἐπίστηθι epistêi, epístēthi formas verbais; remissão ver ἐφίστημι BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπιστῇ, ἐπίστηθι</td><td>formas verbais; remissão</td><td>ver ἐφίστημι</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-episteme-bdag\" data-source=\"BDAG\" data-search=\"ἐπιστήμη, ης, ἡ epistḗmē substantivo feminino conhecimento; entendimento; compreensão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπιστήμη, ης, ἡ</td><td>substantivo feminino</td><td>conhecimento; entendimento; compreensão</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epistemon-bdag\" data-source=\"BDAG\" data-search=\"ἐπιστήμων, ον epistḗmōn adjetivo; genitivo -ονος entendido; instruído; perito; conhecedor BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπιστήμων, ον</td><td>adjetivo; genitivo -ονος</td><td>entendido; instruído; perito; conhecedor</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article id=\"entry-episitismos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπισιτισμός, οῦ, ὁ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦episitismós⟧</span><span class=\"separator\">·</span><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><b>Provisões, mantimentos</b>, como reserva de alimentos (assim Xen., An. 7, 1, 9; Políbio 2, 5, 3; Herodiano 6, 7, 1; OGI 200, 15; Sb 6949, 15; LXX; Jos., Bell. 3, 85). <span class=\"greek\">εὑρίσκειν</span> <span class=\"greek\">ἐ</span>., <i>encontrar ou obter provisões</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.12\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 9:12</a>. — DELG, s.v. <span class=\"greek\">σῖτος</span>; M-M.</p></section></article>\n<article id=\"entry-episkeptomai-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπισκέπτομαι</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦episképtomai⟧</span><span class=\"separator\">·</span><span>verbo; depoente médio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Depoente médio; futuro <span class=\"greek\">ἐπισκέψομαι</span>, LXX; primeiro aoristo <span class=\"greek\">ἐπεσκεψάμην</span>; perfeito <span class=\"greek\">ἐπέσκεμμαι</span>, LXX. Voz passiva: futuro, terceira pessoa do singular <span class=\"greek\">ἐπισκεπήσεται</span>, 1 Km 20:18; aoristo <span class=\"greek\">ἐπεσκέπην</span>, LXX; por outro lado, futuro, terceira pessoa do singular <span class=\"greek\">ἐπισκεφθήσεται</span>, Jr 3:16, e subjuntivo aoristo, terceira pessoa do singular <span class=\"greek\">ἐπισκεφθῇ</span>, 1 Esdr 2:16 (ver <span class=\"greek\">σκοπέω</span>; poetas trágicos, Heródoto e posteriores; B-D-F §101, p. 48, s.v. <span class=\"greek\">σκοπεῖν</span>; Mlt-H. 258, s.v. -<span class=\"greek\">σκέπτομαι</span>).</p>\n<p class=\"entry-text\"><b>① Fazer uma inspeção cuidadosa: olhar, examinar, inspecionar.</b> (Heródoto 2, 109, 2 e outros.) Com acusativo (Diod. S. 12, 11, 4; Nm 1:3; 1 Km 13:15; 2 Km 18:1), Hs 8, 2, 9; 8, 3, 3; 9, 10, 4; 1 Cl 25:5. Também <b>procurar com interesse visando à escolha: selecionar</b>, com acusativo (PPetr II, 37, 2b, verso 4 [séc. III a.C.]: <span class=\"greek\">ἐπισκεψάμενος</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἀρχῇ</span> <span class=\"greek\">ἃ</span> <span class=\"greek\">δεῖ</span> <span class=\"greek\">γενέσθαι</span> <span class=\"greek\">ἔργα</span>), <span class=\"greek\">ἄνδρας</span>, <i>homens</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.6.3\" target=\"_blank\" rel=\"noopener noreferrer\">At 6:3</a>.</p>\n<p class=\"entry-text\"><b>② Ir ver uma pessoa com a intenção de ajudá-la: visitar.</b> Com <span class=\"greek\">τινά</span>, <i>alguém</i> (Demóstenes 9, 12; PLille 6, 5 [séc. III a.C.]: <span class=\"greek\">διαβάντος</span> <span class=\"greek\">μου</span> … <span class=\"greek\">ἐπισκέψασθαι</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἀδελφήν</span>; Jz 15:1). <span class=\"greek\">ἀνέβη</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">καρδίαν</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">ἐπισκέψασθαι</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">ἀδελφούς</span> <span class=\"greek\">αὐτοῦ</span>, <i>(Moisés) sentiu no coração forte desejo de visitar seus irmãos, seu povo</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.23\" target=\"_blank\" rel=\"noopener noreferrer\">At 7:23</a> (quanto à solicitude, cf. Xen., Mem. 3, 11, 10: <span class=\"greek\">φροντιστικῶς</span>); <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.36\" target=\"_blank\" rel=\"noopener noreferrer\">At 15:36</a>. <span class=\"greek\">ἀλλήλους</span>, <i>uns aos outros</i>, Hv 3, 9, 2. Especialmente acerca de <b>visitar enfermos</b> (Xen., Mem. 3, 11, 10; Plut., Mor. 129c; Luciano, Philops. 6; Herodiano 4, 2, 4; Sir 7:35; TestJob 28:2; Jos., Ant. 9, 178), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.36\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25:36</a>, 43; Pol 6:1. Quando o contexto indica especialmente o cuidado a ser dispensado: <b>assistir a viúvas e órfãos</b> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">θλίψει</span> <span class=\"greek\">αὐτῶν</span>, <i>em sua aflição</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.27\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 1:27</a>; cf. Hs 1:8; <span class=\"greek\">ὀρφανοὺς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ὑστερουμένους</span>, <i>órfãos e necessitados</i>, Hm 8:10.</p>\n<p class=\"entry-text\"><b>③ Exercer supervisão em benefício de alguém: cuidar, manifestar-se para ajudar</b>, acerca do cuidado divino (Gn 21:1; 50:24s.; Êx 3:16; 4:31; Sir 46:14; Jt 8:33; En 25:3; TestLevi 16:5; PsSol 9:4; JosAs 7:35; Just., D. 29, 1), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.68\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 1:68</a>. <span class=\"greek\">ἐπισκέψεται</span> <span class=\"greek\">ἡμᾶς</span> <span class=\"greek\">ἀνατολὴ</span> <span class=\"greek\">ἐξ</span> <span class=\"greek\">ὕψους</span>, <i>uma aurora do alto nos visitará</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.78\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 1:78</a> (a imagem é a da luz nascente, que torna possível enxergar; a inspeção divina beneficia os oprimidos; a NRSV, «irromper sobre», desloca a imagem); <span class=\"greek\">τὸν</span> <span class=\"greek\">λαόν</span>, <i>o povo</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.16\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 7:16</a> (cf. Rt 1:6). Acerca de Joaquim, que se achava sem filhos: <span class=\"greek\">ἐπισκέψηταί</span> <span class=\"greek\">με</span> <span class=\"greek\">κύριος</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θεός</span> <span class=\"greek\">μου</span>, <i>que o Senhor, meu Deus, me visite</i>, GJs 1:4; <span class=\"greek\">ὅπως</span> <span class=\"greek\">ἐπισκέψηταί</span> <span class=\"greek\">με</span>, <i>para que (Deus) venha em meu auxílio</i>, GJs 2:4 (cf. códice A; ver Tischendorf); <span class=\"greek\">ὅτι</span> <span class=\"greek\">ἐπεσκέψατό</span> <span class=\"greek\">με</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἀφεῖλεν</span> … <span class=\"greek\">ὀνειδισμόν</span>, <i>porque me visitou e afastou … a vergonha</i>, GJs 6:3. — <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.6\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2:6</a> (Sl 8:5). <b>Preocupar-se com</b>, seguido de infinitivo (ver B-D-F §392, 3): <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">ἐπεσκέψατο</span> <span class=\"greek\">λαβεῖν</span> <span class=\"greek\">ἐξ</span> <span class=\"greek\">ἐθνῶν</span> <span class=\"greek\">λαόν</span>, <i>Deus cuidou de adquirir dentre as nações um povo</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.14\" target=\"_blank\" rel=\"noopener noreferrer\">At 15:14</a>. — M-M; TW; Sv.</p></section></article>\n<article id=\"entry-episkeuazomai-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπισκευάζομαι</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦episkeuázomai⟧</span><span class=\"separator\">·</span><span>verbo; médio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Ver <span class=\"greek\">σκεῦος</span>.) Primeiro aoristo <span class=\"greek\">ἐπεσκευασάμην</span>; infinitivo passivo <span class=\"greek\">ἐπισκευασθήναι</span>, 1 Km 3:3 (em geral, na voz ativa — Aristófanes, Tucídides e outros; inscrições, papiros, LXX; em nossa literatura, somente médio, como Jos., Bell. 1, 297). <b>Preparar-se para uma atividade ou objetivo: aprontar-se</b> (Tucídides 7, 36, 2), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.15\" target=\"_blank\" rel=\"noopener noreferrer\">At 21:15</a>. — DELG, s.v. <span class=\"greek\">σκεῦος</span>; M-M, s.v. <span class=\"greek\">ἐπισκευάζω</span>.</p></section></article>\n<article id=\"entry-episkenoo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπισκηνόω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦episkēnóō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Primeiro aoristo <span class=\"greek\">ἐπεσκήνωσα</span> (<span class=\"greek\">σκηνόω</span>, «armar tendas»; ver <span class=\"greek\">σκηνή</span>). <b>Utilizar um lugar para alojamento: estabelecer-se, fixar residência, habitar.</b> Com <span class=\"greek\">ἐπί</span> e acusativo do lugar onde se estabelece (Políbio 4, 18, 8: <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">οἰκίας</span>, sobre tropas alojadas em casas), <span class=\"greek\">ἵνα</span> <span class=\"greek\">ἐπισκηνώσῃ</span> <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">ἐμὲ</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">δύναμις</span> <span class=\"greek\">τ</span>. <span class=\"greek\">Χριστοῦ</span>, <i>para que o poder de Cristo habite em mim</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.12.9\" target=\"_blank\" rel=\"noopener noreferrer\">2 Co 12:9</a>. — DELG, s.v. <span class=\"greek\">σκηνή</span>; M-M; TW.</p></section></article>\n<article id=\"entry-episkiazo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπισκιάζω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦episkiázō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Futuro, terceira pessoa do singular, <span class=\"greek\">ἐπισκιάσει</span>, Sl 90:4; primeiro aoristo <span class=\"greek\">ἐπεσκίασα</span> (<span class=\"greek\">σκιάζω</span>, «fazer sombra, escurecer»; ver <span class=\"greek\">σκιά</span>; Heródoto e outros; Fílon, Deus Imm. 3 e frequentemente; LXX; Just., A I, 33, 6; Ath. 30, 2).</p>\n<p class=\"entry-text\"><b>① Produzir escurecimento pela interposição de algo entre uma fonte de luz e um objeto: fazer sombra sobre, projetar sombra.</b> (Aristóteles, Gen. An. 5, 1; Teofrasto, C. Pl. 2, 18, 3.) Com dativo <span class=\"greek\">τινί</span>, <i>sobre alguém</i> (Teofrasto, De Sens. 79): <span class=\"greek\">ἵνα</span> <span class=\"greek\">κἂν</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">σκιὰ</span> <span class=\"greek\">ἐπισκιάσῃ</span> <span class=\"greek\">τινὶ</span> <span class=\"greek\">αὐτῶν</span>, <i>para que ao menos sua sombra recaísse sobre algum deles</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.15\" target=\"_blank\" rel=\"noopener noreferrer\">At 5:15</a>.</p>\n<p class=\"entry-text\"><b>② Provocar escurecimento: cobrir, envolver em sombra.</b> (Heródoto 1, 209: <span class=\"greek\">τῇ</span> <span class=\"greek\">πτέρυγι</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">Ἀσίην</span>; Eliano, VH 3, 3.) Com acusativo de pessoa; em nossa literatura, sobretudo sobre a ação divina, como uma nuvem que assinala a presença de Deus (cf. Êx 40:35; OdesSol 35, 1): <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.17.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 17:5</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.34\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 9:34</a>. Com dativo (Sl 90:4): <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 9:7</a>. Com acusativo de coisa: <span class=\"greek\">ἦν</span> <span class=\"greek\">νεφέλη</span> <span class=\"greek\">σκοτεινὴ</span> <span class=\"greek\">ἐπισκιάζουσα</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">σπήλαιον</span>, <i>uma nuvem escura pairava sobre a gruta</i> (onde Jesus nasceu), GJs 19:2.</p>\n<p class=\"entry-text\">Essa perspectiva também está presente no relato da concepção singular de Maria: <span class=\"greek\">δύναμις</span> <span class=\"greek\">ὑψίστου</span> <span class=\"greek\">ἐπισκιάσει</span> <span class=\"greek\">σοι</span>, <i>o poder do Altíssimo te cobrirá com sua sombra</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.35\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 1:35</a>. Quanto às imagens de sombreamento que envolvem o divino e o humano, cf. Fílon, Rer. Div. Her. 265 M 511, De Somniis 1, 119 M 638; ver Leisegang (abaixo), pp. 25s.; mas, contra a sugestão de Leisegang de conteúdo politeísta, ver R. Brown, <i>The Birth of the Messiah</i> (1977), p. 290. GJs 11:3; mas Just., A I, 33, 4 e D. 100, 5 emprega <span class=\"greek\">αὐτήν</span>.</p>\n<p class=\"entry-text\">Sobre essa passagem, ver J. Hehn, BZ 14 (1917), pp. 147–152; A. Allgeier, ibid., pp. 338ss.; <i>Byz.-Neugriech. Jahrb.</i> 1 (1920), pp. 131–141; <i>Histor. Jahrbuch</i> 45 (1925), pp. 1ss.; H. Leisegang, <i>Pneuma Hagion</i> (1922), pp. 24ss.; E. Norden, <i>D. Geburt des Kindes</i> (1924), pp. 92–99; L. Radermacher, <i>P. Kretschmer Festschr.</i> (1926), pp. 163ss.; A. Fridrichsen, SymbOsl 6 (1928), pp. 33–36; M. Dibelius, <i>Jungfrauensohn u. Krippenkind</i>, SBHeidAk 1931/32, quarta dissertação (1932), pp. 23s. e 41; H. von Baer, <i>D. Hl. Geist in d. Lkschriften</i> (1926), pp. 124ss.; K. Bornhäuser, <i>D. Geburts-u. Kindheitsgesch. Jesu</i> (1930), pp. 81ss.; S. Lösch, <i>Deitas Iesu u. antike Apotheose</i> (1933), p. 101; R. Brown, <i>The Birth of the Messiah</i> (1977), pp. 290s., 292–309. — DELG, s.v. <span class=\"greek\">σκιά</span>; M-M; EDNT; TW; Sv.</p></section></article>\n<article id=\"entry-episkopeo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπισκοπέω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦episkopéō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Futuro <span class=\"greek\">ἐπισκοπήσω</span>; primeiro aoristo <span class=\"greek\">ἐπεσκόπησα</span>; particípio perfeito passivo <span class=\"greek\">ἐπεσκοπημένος</span> (ver <span class=\"greek\">σκοπέω</span> e o verbete seguinte; Ésquilo e outros).</p>\n<p class=\"entry-text\"><b>① Dar atenção a alguma coisa: observar, cuidar, certificar-se de.</b> Seguido de <span class=\"greek\">μή</span> (Fílon, Decal. 98), com a implicação de um perigo que ameaça alguém, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.15\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:15</a>.</p>\n<p class=\"entry-text\"><b>② Assumir a responsabilidade de cuidar de alguém: supervisionar, zelar por.</b> (Platão, Rep. 6, p. 506a: <span class=\"greek\">τὴν</span> <span class=\"greek\">πολιτείαν</span>; Dio Chrys. 8 [9], 1, da missão de vida do cínico Diógenes; LBW 2309; 2412e; papiros [Witkowski 52, 12; cf. 63, 18; 71, 43]; 2 Cr 34:12.) Daí, no sentido distintivamente cristão da atividade de dirigentes das comunidades, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.5.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pe 5:2</a>; particularmente de quem recebeu a incumbência da supervisão: <b>ser supervisor</b>, com <span class=\"greek\">τινά</span>, <i>sobre alguém</i>; acerca de Jesus, o supervisor ideal, IRo 9:1. Num jogo de palavras com <span class=\"greek\">ἐπίσκοπος</span>: <span class=\"greek\">ἐπισκόπῳ</span> <span class=\"greek\">μᾶλλον</span> <span class=\"greek\">ἐπισκοπημένῳ</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">θεοῦ</span>, <i>o supervisor, que, antes, é supervisionado por Deus</i> = «o bispo que tem Deus por seu bispo», IPol, inscrição (sobre <span class=\"greek\">ἐπισκοπέω</span> aplicado a Deus, ver Jos., C. Ap. 2, 160). Em uso absoluto: <b>servir como supervisor</b>, Hv 3, 5, 1. — DELG, s.v. <span class=\"greek\">σκέπτομαι</span>; M-M; TW.</p></section></article>\n<article id=\"entry-episkope-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπισκοπή, ῆς, ἡ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦episkopḗ⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Ver o verbete precedente; Luciano, D. Deor. 20, 6 = «visita»; OGI 614, 6 [séc. III d.C.] = «cuidado, encargo»; Etym. Gud. 508, 27 = <span class=\"greek\">πρόνοια</span>; LXX; TestBenj 9:2; JosAs 29, final do códice A: <span class=\"greek\">ἐπισκοπῇ</span> <span class=\"greek\">ἐπισκέπτεσθαί</span> <span class=\"greek\">τινα</span>, acerca de Deus; Just., D. 131, 3).</p>\n<p class=\"entry-text\"><b>① Ato de velar por alguém, com referência especial à presença: visitação</b>, acerca da ação divina.</p>\n<p class=\"entry-text\"><b>ⓐ De caráter benéfico, salutar.</b> (Assim Gn 50:24s.; Êx 3:16; Sb 2:20; 3:13; Jó 10:12; 29:4 e outros.) <span class=\"greek\">καιρὸς</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἐ</span>., <i>o tempo da tua visitação graciosa</i> (Sb 3:7), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.44\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 19:44</a>. <span class=\"greek\">ἐν</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">βασιλείας</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Χριστοῦ</span>, <i>quando o Reino de Cristo nos visita</i>, 1 Cl 50:3. <span class=\"greek\">ἡμέρα</span> <span class=\"greek\">ἐπισκοπῆς</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pe 2:12</a>, é interpretado nesse sentido pela maioria (por exemplo Usteri, B. Weiss, Kühl, Knopf, Windisch, F. Hauck e outros). Ver também ⓑ abaixo. A visitação benevolente pode manifestar-se como <b>proteção, cuidado</b> (Jó 10:12; Pv 29:13; 3 Mac 5:42; Just., D. 131, 3; Orígenes, C. Cels. 6, 71, 8 [cuidado providencial, com <span class=\"greek\">πρόνοια</span>]): <span class=\"greek\">ἐν</span> <span class=\"greek\">ἑνότητι</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἐπισκοπῇ</span>, <i>em unidade com Deus e sob seu cuidado</i>, IPol 8:3.</p>\n<p class=\"entry-text\"><b>ⓑ De caráter desagradável, punitivo.</b> (Hesíquio = <span class=\"greek\">ἐκδίκησις</span>; Jr 10:15; Sir 16:18; 23:24; Sb 14:11; Teófilo de Antioquia 2, 35 [p. 188, 26].) <span class=\"greek\">ἡμέρα</span> <span class=\"greek\">ἐ</span>. (cf. Is 10:3), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pe 2:12</a>, assim compreendido pela minoria (por exemplo H. von Soden, Bigg, Goodspeed; Danker, ZNW 58 [1967], pp. 98s., com referência a Ml 3:13–18). Ver ⓐ acima.</p>\n<p class=\"entry-text\"><b>② Posição de responsabilidade: posição, incumbência, atribuição.</b> (Nm 4:16.) Acerca da posição de Judas como apóstolo: <span class=\"greek\">τὴν</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">λαβέτω</span> <span class=\"greek\">ἕτερος</span>, <i>assuma outro a sua tarefa</i> — não um cargo, como tal, mas a atividade de testemunhar segundo as especificações de <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">At 1:8</a>, 21s. —, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">At 1:20</a> (Sl 108:8).</p>\n<p class=\"entry-text\"><b>③ Exercício da supervisão: superintendência</b>, por dirigentes de comunidades cristãs (inscrição cristã da Licaônia [séc. IV d.C.], CB I/2, p. 543; Irineu 3, 3, 3 [Harv. II 10, 2] e outros; Orígenes, C. Cels. 3, 48, 20), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.3.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Tm 3:1</a> (ver U. Holzmeister, Biblica 12 [1931], pp. 41–69; C. Spicq, RSPT 29 [1940], pp. 316–325); 1 Cl 44:1, 4. — DELG, s.v. <span class=\"greek\">σκέπτομαι</span>; M-M; EDNT; TW.</p></section></article>\n<article id=\"entry-episkopos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπίσκοπος, ου, ὁ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epískopos⟧</span><span class=\"separator\">·</span><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Ver o verbete precedente; Homero e outros; Diod. S. 37, 28, 1 [acerca de um rei, com o sinônimo <span class=\"greek\">θεατής</span>]; inscrições, papiros, LXX; JosAs 15:7, códice A [p. 61, 16 Bat.]: <span class=\"greek\">μετάνοια</span> … <span class=\"greek\">ἐπίσκοπος</span> <span class=\"greek\">πάντων</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">παρθένων</span>; Fílon, Josefo. — L. Porter, «The Word <span class=\"greek\">ἐπίσκοπος</span> in Pre-Christian Usage», ATR 21 [1939], pp. 103–112.) Em geral, «alguém que vela por, guardião». B. Thiering, «‘Mebaqqer’ and ‘Episkopos’ in the Light of the Temple Scroll», JBL 100 (1981), pp. 59–74, sustenta que o ofício de «bispo» foi adotado das comunidades leigas essênias; cf. CD 14, 8–12; hebraico <span class=\"hebrew\">בקר</span>, Ez 34:11 [LXX <span class=\"greek\">ἐπισκέπτειν</span>].</p>\n<p class=\"entry-text\"><b>① Alguém incumbido de salvaguardar ou garantir que alguma coisa seja realizada corretamente: guardião.</b> (Assim Il. 22, 255: divindades como guardiãs de acordos, isto é, cuidam para que estes sejam cumpridos; Ésquilo, Sept. 272; Sófocles, Ant. 1148; Platão, Leg. 4, 717d; Plut., Cam. 5, 6: <span class=\"greek\">θεοὶ</span> <span class=\"greek\">χρηστῶν</span> <span class=\"greek\">ἐπίσκοποι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πονηρῶν</span> <span class=\"greek\">ἔργων</span>; Máximo de Tiro 5, 8e: <span class=\"greek\">ὦ</span> <span class=\"greek\">Ζεῦ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">Ἀθηνᾶ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">Ἄπολλον</span>, <span class=\"greek\">ἐθῶν</span> <span class=\"greek\">ἀνθρωπίνων</span> <span class=\"greek\">ἐπίσκοποι</span>; Bábrio 11, 4 P. ’84 = L-P.; Herodiano 7, 10, 3; frequentemente Cornuto, edição de Lang, índice; SIG 1240, 21; UPZ 144, 49 [164 a.C.]; PGM 4, 2721; Jó 20:29; Sb 1:6; Fílon, Migr. Abr. 115 e outros; SibOr, fragmento 1, 3.) <span class=\"greek\">παντὸς</span> <span class=\"greek\">πνεύματος</span> <span class=\"greek\">κτίστης</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἐπίσκοπος</span>, <i>criador e guardião de todo espírito</i>, 1 Cl 59:3. Acerca de Cristo (com <span class=\"greek\">ποιμήν</span>): <span class=\"greek\">ἐ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">ψυχῶν</span>, <i>guardião das almas</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.25\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pe 2:25</a>. As passagens IMg 3:1, <span class=\"greek\">θεῷ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">πάντων</span> <span class=\"greek\">ἐ</span>., e cf. 6:1 demonstram a transição para o significado seguinte.</p>\n<p class=\"entry-text\"><b>② No mundo greco-romano, a palavra designa frequentemente quem exerce função definida ou cargo fixo de guarda e atividades correlatas num grupo.</b> (Aristófanes, Av. 1023; IG XII/1, 49, 43ss. [sécs. II/I a.C.], 50, 34ss. [séc. I a.C.]; LBW 1989; 1990; 2298; Nm 31:14 e outros; PPetr III, 36a, verso 16 [séc. III a.C.]; Jos., Ant. 10, 53; 12, 254.) Inclui grupos religiosos (IG XII/1, 731, 8: um <span class=\"greek\">ἐ</span>. no templo de Apolo em Rodes; ver Deissmann, NB 57s. [BS 230s.]; cf. também Nm 4:16). Sobre o pregador cínico-estoico como <span class=\"greek\">ἐπισκοπῶν</span> e <span class=\"greek\">ἐπίσκοπος</span>, ver E. Norden, <i>Jahrb. klass. Phil.</i>, suplemento 19 (1893), pp. 377ss.; Fílon, Rer. Div. Her. 30, Moisés como <span class=\"greek\">ἐ</span>..</p>\n<p class=\"entry-text\">O termo foi adotado pelas comunidades cristãs para alguém que atuava como <b>supervisor, dirigente encarregado de vigiar e preservar especialmente a tradição apostólica</b> (Irineu, Orígenes, Hipólito): <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.28\" target=\"_blank\" rel=\"noopener noreferrer\">At 20:28</a> (R. Schnackenburg, <i>Schriften zum NT</i> [1971], pp. 247–267; E. Löwestam, «Paul’s Address at Miletus», StTh 41 [1987], pp. 1–10); com <span class=\"greek\">διάκονοι</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.1\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 1:1</a> (J. Reumann, NTS 39 [1993], pp. 446–450); D 15:1; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Tm 3:2</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">Tt 1:7</a> (ver B. Easton, <i>Pastoral Epistles</i> [1947], pp. 173, 177, 227). <span class=\"greek\">ἀπόστολοι</span>, <span class=\"greek\">ἐ</span>., <span class=\"greek\">διδάσκαλοι</span>, <span class=\"greek\">διάκονοι</span>, Hv 3, 5, 1; com <span class=\"greek\">φιλόξενοι</span>, Hs 9, 27, 2. Especialmente frequente em Inácio: IEph 1:3; 2:1s.; 3:2; 4:1; 5:1s. e muitas outras passagens; subscrição de 2 Tm: Timóteo, supervisor dos efésios; subscrição de Tt: Tito, supervisor dos cristãos cretenses.</p>\n<p class=\"entry-text\">O empréstimo eclesiástico «bispo» é excessivamente técnico e carregado de significados históricos tardios para exprimir com precisão o uso de <span class=\"greek\">ἐπίσκοπος</span> e seus cognatos em nossa literatura, sobretudo no NT.</p>\n<p class=\"entry-text\"><b>Bibliografia sobre a organização das comunidades cristãs:</b> E. Hatch–A. Harnack, <i>D. Gesellschaftsverf. d. christ. Kirchen im Altert.</i> (1883); Harnack, <i>D. Lehre d. 12 Apostel</i> (1884), pp. 88ss.; <i>Entstehung u. Entwicklung der Kirchenverfassung u. des Kirchenrechts in d. zwei ersten Jahrh.</i> (1910); E. Loening, <i>D. Gemeindeverf. d. Urchristent.</i> (1888); C. Weizsäcker, <i>D. apost. Zeitalter</i>² (1892), pp. 613ss.; R. Sohm, <i>Kirchenrecht</i> I (1892); J. Réville, <i>Les origines de l’épiscopat</i> (1894); H. Bruders, <i>D. Verf. d. Kirche bis z. J. 175</i> (1904); R. Knopf, <i>D. nachapostl. Zeitalter</i> (1905), pp. 147ss.; P. Batiffol–F. Seppelt, <i>Urkirche u. Katholicismus</i> (1910), pp. 101ss.; O. Scheel, «Z. urchristl. Kirchen-u. Verfassungsproblem», StKr 85 (1912), pp. 403–457; H. Lietzmann, «Z. altchr. Verfassungsgesch.», ZWT 55 (1913), pp. 101–106 (= <i>Kleine Schriften</i> I [1958], pp. 144–148); E. Metzner, <i>D. Verf. d. Kirche in d. zwei ersten Jahrh.</i> (1920); K. Müller, «Beiträge z. Gesch. d. Verf. in d. alten Kirche», ABA (1922), n.º 3; H. Dieckmann, <i>D. Verf. d. Urkirche</i> (1923); G. von Hultum, ThGl 19 (1927), pp. 461–488; G. Holstein, <i>D. Grundlagen d. evangel. Kirchenrechts</i> (1928); J. Jeremias, <i>Jerusalem</i> II B 1 (1929), pp. 132ss. (contra ele, K. Goetz, ZNW 30 [1931], pp. 89–93); B. Streeter, <i>The Primitive Church</i> (1929); O. Linton, <i>D. Problem d. Urkirche usw.</i> (1932), com bibliografia desde 1880; J. Lebreton–J. Zeiller, <i>L’Eglise primitive</i> (1934); H. Beyer, «D. Bischofamt im NT», <i>Deutsche Theologie</i> 1 (1934), pp. 201–225; H. Greeven, «Propheten, Lehrer, Vorsteher bei Pls», ZNW 44 (1952/53), pp. 1–43 (com bibliografia); H. von Campenhausen, <i>Kirchl. Amt u. geistl. Vollmacht in den ersten 3 Jahrhunderten</i> (1953); W. Michaelis, <i>Das Ältestenamt der christlichen Gemeinde im Lichte der Hl. Schrift</i> (1953); R. Bultmann, <i>Theol. of the NT</i> (trad. K. Grobel, 1955), II, pp. 95–111; T. Manson, <i>The Church’s Ministry</i> (1956); F. Nötscher, <i>Vom Alten zum NT</i> (1962), pp. 188–220; D. Moody, <i>Interpretation</i> 19 (1965), pp. 168–181; H. Braun, <i>Qumran u. das NT</i> (1966), II, pp. 326–342; RGG³ I, pp. 335–337 (com bibliografia); J. Fitzmyer, <i>P. Schubert Festschr.</i> (1966), pp. 256s., nota 41 (com bibliografia); RAC II, pp. 394–407; R. Brown, TS 41 (1980), pp. 322–338 (revisão dos dados do NT). — Poland 377; M-M; EDNT; TW; Sv.</p></section></article>\n<article id=\"entry-episkoteo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπισκοτέω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦episkotéō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Ver os verbetes em <span class=\"greek\">σκοτ</span>-; Hipócrates, Platão e outros; Jos., Bell. 5, 343, C. Ap. 1, 214; Ath.) Em geral, «escurecer, obscurecer».</p>\n<p class=\"entry-text\"><b>① Colocar alguma coisa no caminho, de modo que não se consiga enxergar adequadamente: impedir de ver.</b> <span class=\"greek\">ἐπισκοτεῖσθαι</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">πράξεων</span>, <i>ser impedido por (essas) ocupações de enxergar</i>, Hm 10, 1, 4 (cf. Fílon, De Jos. 147).</p>\n<p class=\"entry-text\"><b>② Interpor alguma coisa de maneira que um objeto não possa ser distinguido claramente: obscurecer.</b> (Menandro, fragmento 48 Kock e Kö.) Voz passiva: <i>ser obscurecido</i> (Políbio 2, 39, 12: <span class=\"greek\">ἐπισκοτεῖσθαι</span> <span class=\"greek\">κ</span>. <span class=\"greek\">κωλύεσθαι</span>, de pessoas cujas qualificações não são reconhecidas; Heraclito, estoico, 19, p. 29, 15). A respeito do Espírito: <span class=\"greek\">μὴ</span> <span class=\"greek\">ἐπισκοτούμενον</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">ἑτέρου</span> <span class=\"greek\">πονηροῦ</span> <span class=\"greek\">πνεύματος</span>, <i>não sendo obscurecido por outro espírito maligno</i>, Hm 5, 1, 2 (a imagem contrapõe um espírito luminoso e franco [<span class=\"greek\">καθαρόν</span>] a um espírito vil, que obscurece; cf. Diógenes Laércio 5, 76: <span class=\"greek\">ἐπεσκοτήθη</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">φθόνου</span>). — DELG, s.v. <span class=\"greek\">σκότος</span>.</p></section></article>\n<article id=\"entry-epispao-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπισπάω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epispáō⟧</span><span class=\"separator\">·</span><span>verbo; voz média</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(De <span class=\"greek\">σπάω</span>.) Em nossa literatura, somente na voz média (que se encontra desde Heródoto; Herm. Wr.; inscrições, papiros, LXX; TestReub 5:1; JosAs 5:9, códice A [p. 46, 2 Bat.]; Fílon; Jos., Ant. 14, 424; C. Ap. 2, 31). Futuro, terceira pessoa do plural, <span class=\"greek\">ἐπισπάσονται</span>, TestReub 5:1; primeiro aoristo <span class=\"greek\">ἐπεσπασάμην</span>, LXX.</p>\n<p class=\"entry-text\"><b>① Fazer alguma coisa vir até si: atrair para si</b>, literalmente. Com <span class=\"greek\">τινί</span> <span class=\"greek\">τι</span>, acerca de um animal, MPol 3:1 (cf. Diod. S. 17, 13, 2: <span class=\"greek\">ἐπισπᾶσθαι</span> <span class=\"greek\">πληγάσ</span> = <i>atrair os golpes (dos inimigos) para si (a fim de morrer mais depressa)</i>).</p>\n<p class=\"entry-text\"><b>② Ser responsável por trazer alguma coisa sobre si: atrair, acarretar.</b> Extensão figurada de ① (Heródoto 3, 7, 72; Políbio 3, 98, 8; Anth. Pal. 11, 340, 2: <span class=\"greek\">ἔχθραν</span>; OGI 13, 6: <span class=\"greek\">τ</span>. <span class=\"greek\">κρίσιν</span>; Sb 1:12). Com <span class=\"greek\">τί</span> <span class=\"greek\">τινι</span>, <i>alguma coisa sobre alguém</i>: <span class=\"greek\">αἰχμαλωτισμὸν</span> <span class=\"greek\">ἑαυτοῖς</span>, <i>atrair cativeiro sobre si</i>, Hv 1, 1, 8; <span class=\"greek\">ἀσθένειαν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">σαρκὶ</span> <span class=\"greek\">αὐτῶν</span>, <i>fraqueza sobre sua carne</i>, Hv 3, 9, 3; <span class=\"greek\">μεγάλην</span> <span class=\"greek\">ἁμαρτίαν</span> <span class=\"greek\">ἑαυτῷ</span>, <i>grande pecado sobre si</i>, Hm 4, 1, 8; <span class=\"greek\">ἑαυτῷ</span> <span class=\"greek\">λύπην</span>, <i>tristeza sobre si</i>, Hs 9, 2, 6.</p>\n<p class=\"entry-text\"><b>③ Termo técnico da medicina: puxar o prepúcio para cobrir a extremidade do pênis, tracionar o prepúcio.</b> (Sorano, Gynaec. 2, 34, p. 79, 1, acerca de uma ama: <span class=\"greek\">ἐπισπάσθω</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἀκροποσθίαν</span>.) <b>Ocultar a circuncisão</b>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.18\" target=\"_blank\" rel=\"noopener noreferrer\">1 Co 7:18</a> (esse uso específico da palavra não é encontrado em outro lugar, nem mesmo em 4 Mac 5:2, onde <span class=\"greek\">ἐπισπᾶσθαι</span> significa «arrastar para cima», como em 10:12). Sobre o <i>epispasmo</i> [rabínico <span class=\"hebrew\">מ<span class=\"greek\">ָ</span>ש<span class=\"greek\">ַׁ</span>ך<span class=\"greek\">ְ</span></span>], praticado por israelitas helenizantes, sobretudo efebos, para desfazer a aparência da circuncisão, ver 1 Mac 1:15; Jos., Ant. 12, 241; Billerb. IV, pp. 33s.; M. Hengel, <i>Judaism and Hellenism</i> (1974), I, p. 74; II, pp. 51s., nota 138 (com bibliografia); R. Hall, «Epispasm—Circumcision in Reverse», BR 18/4 (1992), pp. 52–57. — M-M.</p></section></article>\n<article id=\"entry-epispeiro-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπισπείρω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epispeírō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Primeiro aoristo <span class=\"greek\">ἐπέσπειρα</span> (ver <span class=\"greek\">σπείρω</span>; desde Píndaro, N. 8, 39; Heródoto; Ath. 33, 1). <b>Semear sobre uma cultura já plantada; semear posteriormente</b>, termo técnico da agricultura (Teofrasto, HP 7, 1, 3, acerca da semeadura de aipo sobre outra plantação já estabelecida; 5, 4, sobre semear ervilhaca amarga para proteger uma cultura de rabanetes contra aranhas, e outros). Com <span class=\"greek\">τὶ</span>, <i>alguma coisa</i>: <span class=\"greek\">ζιζάνια</span> <span class=\"greek\">ἀνὰ</span> <span class=\"greek\">μέσον</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">σίτου</span>, <i>joio em meio ao trigo</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:25</a>. — M-M.</p></section></article>\n<article id=\"entry-epispoudazo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπισπουδάζω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epispoudázō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Ver <span class=\"greek\">σπουδάζω</span>, <span class=\"greek\">σπουδή</span>; Luciano, Pisc. 2; PHib 49, 3 [séc. III a.C.]; PLille 3, 27; LXX.) <b>Demonstrar zelo adicional, ser ainda mais zeloso.</b> Com <span class=\"greek\">περί</span> <span class=\"greek\">τινος</span>, <i>por alguém</i>; entretanto, o texto provavelmente está corrompido: o prefixo <span class=\"greek\">ἐπί</span> pode ter sido repetido por influência do <span class=\"greek\">ἔτι</span> precedente em Hs 2:6, variante de leitura (cf. a sonoridade das palavras em POxy 1172: <span class=\"greek\">ἔτι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἔτι</span> <span class=\"greek\">ἐπισπουδάζει</span>; ver M. Dibelius, Hdb., ad loc.). Ver Whittaker, nota marginal. — DELG, s.v. <span class=\"greek\">σπεύδω</span>.</p></section></article>\n<article id=\"entry-epistamai-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπίσταμαι</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epístamai⟧</span><span class=\"separator\">·</span><span>verbo; depoente passivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Depoente passivo; imperfeito <span class=\"greek\">ἠπιστάμην</span>, Dg 8:1 (ver <span class=\"greek\">ἐπιστήμη</span>; Homero e posteriores; inscrições, papiros, LXX, pseudoepígrafos, Fílon, Josefo; Justino; Melitão, HE 4, 26, 13).</p>\n<p class=\"entry-text\"><b>① Adquirir compreensão mental firme de alguma coisa: compreender, entender.</b> Com <span class=\"greek\">τὶ</span>, <i>alguma coisa</i> (Xen., Symp. 3, 6; Sb 8:8; Just., A I, 60, 11): <span class=\"greek\">μηδὲν</span> <span class=\"greek\">ἐπιστάμενος</span>, <i>sem compreender coisa alguma</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Tm 6:4</a>. Em uso absoluto (com <span class=\"greek\">οἶδα</span>), seguido de oração relativa: <span class=\"greek\">σὺ</span> <span class=\"greek\">τί</span> <span class=\"greek\">λέγεις</span>, <i>o que dizes</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.68\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 14:68</a>.</p>\n<p class=\"entry-text\"><b>② Adquirir informação acerca de algo: saber, conhecer, estar familiarizado com.</b> Com <span class=\"greek\">τινά</span>, <i>alguém</i> (Aristófanes, Eq. 1278: <span class=\"greek\">Ἀρίγνωτον</span>; Musônio 3, p. 12, 5 H.; Plut., Cic. 883 [44, 5]; Luciano, Dial. Mort. 9, 3; PGM 13, 844; Sb 15:3; Jos., C. Ap. 1, 175; Just., A I, 63, 15): <span class=\"greek\">τὸν</span> <span class=\"greek\">Παῦλον</span>, <i>Paulo</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.15\" target=\"_blank\" rel=\"noopener noreferrer\">At 19:15</a>; <span class=\"greek\">τὸν</span> <span class=\"greek\">θεόν</span>, <i>Deus</i>, PtK 2, p. 14, 11.</p>\n<p class=\"entry-text\">Com <span class=\"greek\">τὶ</span>, <i>alguma coisa</i> (Homero, Heródoto e outros; Luciano, D. Deor. 25, 2; PRyl 243, 6; Nm 32:11; 1 Esdr 8:23 e outros; PsSol 14:8; ApcSed 8:11; Jos., C. Ap. 1, 15; Just., A I, 58, 2; 60, 5 e outros; Melitão, HE 4, 26, 13): Jd 10; <span class=\"greek\">πολλά</span>, <i>muitas coisas</i>, B 1:4; <span class=\"greek\">τὸ</span> <span class=\"greek\">βάπτισμα</span> <span class=\"greek\">Ἰωάννου</span>, <i>o batismo de João</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.25\" target=\"_blank\" rel=\"noopener noreferrer\">At 18:25</a>; <span class=\"greek\">τὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">αὔριον</span>, <i>o que sucederá amanhã</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.4.14\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 4:14</a>; <span class=\"greek\">τὰς</span> <span class=\"greek\">γραφάς</span>, <i>as Escrituras</i>, 1 Cl 53:1 (cf. Just., D. 70, 5: <span class=\"greek\">τὰ</span> <span class=\"greek\">γράμματα</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">γραφῶν</span>).</p>\n<p class=\"entry-text\">Com <span class=\"greek\">περί</span> <span class=\"greek\">τινος</span>, <i>saber acerca de alguma coisa</i> (Tucídides 6, 60, 1; Platão, Euthyphr. 4e): <span class=\"greek\">ἐπίσταται</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">τούτων</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">βασιλεύς</span>, <i>o rei sabe dessas coisas</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.26\" target=\"_blank\" rel=\"noopener noreferrer\">At 26:26</a>.</p>\n<p class=\"entry-text\">Seguido de <span class=\"greek\">ὅτι</span> (Xen., An. 1, 4, 8 e outros; Êx 4:14; Tb 11:7; TestSol 5:11; TestJob 12:3; Just., A I, 26, 7 e outros): <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.7\" target=\"_blank\" rel=\"noopener noreferrer\">At 15:7</a>; 19:25; 22:19; 1 Cl 45:3. Também com <span class=\"greek\">ὡς</span> (Sófocles, Aj. 1370; Xen., Cyr. 2, 3, 22): <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.28\" target=\"_blank\" rel=\"noopener noreferrer\">At 10:28</a>.</p>\n<p class=\"entry-text\">Seguido de <b>pergunta indireta</b>: <span class=\"greek\">πῶς</span> <span class=\"greek\">ἐγενόμην</span>, <i>como me comportei</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.18\" target=\"_blank\" rel=\"noopener noreferrer\">At 20:18</a> (cf. PTebt 408, 3 [3 d.C.]: <span class=\"greek\">ἐπιστάμενος</span> <span class=\"greek\">πῶς</span> <span class=\"greek\">σε</span> <span class=\"greek\">φιλῶ</span>; Just., A I, 21, 2: <span class=\"greek\">πόσους</span> … <span class=\"greek\">υἰοὺς</span> <span class=\"greek\">φάσκουσι</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Διός</span> = <i>[sabeis] quantos … eles afirmam serem filhos de Zeus</i>); <span class=\"greek\">ποῦ</span> <span class=\"greek\">ἔρχεται</span>, <i>para onde vai</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.8\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:8</a>; <span class=\"greek\">πῶς</span> <span class=\"greek\">νοήσω</span> <span class=\"greek\">αὐτόν</span>, <i>como o compreenderei</i>, Hm 6, 2, 5.</p>\n<p class=\"entry-text\">Com <b>acusativo e particípio</b> (Xen., An. 6, 6, 17; Jos., Vi. 142; Just., D. 49, 1 e 3 e outros): <span class=\"greek\">ὄντα</span> <span class=\"greek\">σε</span> <span class=\"greek\">κριτήν</span>, <i>que és juiz</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.10\" target=\"_blank\" rel=\"noopener noreferrer\">At 24:10</a>; <span class=\"greek\">πολλοὺς</span> <span class=\"greek\">παραδεδωκότας</span> <span class=\"greek\">ἑαυτούς</span>, <i>muitos que se entregaram</i>, 1 Cl 55:2.</p>\n<p class=\"entry-text\">Com <b>infinitivo</b> (Just., A I, 68, 3: <span class=\"greek\">ἐπίστασθαι</span> <span class=\"greek\">δίκαια</span> <span class=\"greek\">ἀξιοῦν</span>; com acusativo e infinitivo, Just., A I, 5, 2: <span class=\"greek\">μὴ</span> <span class=\"greek\">ἐπιστάμενοι</span> <span class=\"greek\">δαίμονας</span> <span class=\"greek\">εἶναι</span> <span class=\"greek\">φαῦλους</span> = <i>sem saber que [os deuses que temem] são, na realidade, espíritos malignos</i>), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.5.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ts 5:3</a>, variante de leitura (ver <span class=\"greek\">ἐφίστημι</span>). — B. 1210; DELG; M-M; TW; Sv.</p></section></article>\n<article id=\"entry-epistas-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιστάς</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epistás⟧</span><span class=\"separator\">·</span><span>forma verbal; remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><b>Remissão:</b> <span class=\"greek\">ἐπιστάς</span>: ver <span class=\"greek\">ἐφίστημι</span>.</p></section></article>\n<article id=\"entry-epistasis-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπίστασις, εως, ἡ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epístasis⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Ver <span class=\"greek\">ἐφίστημι</span> e o verbete seguinte; Sófocles e outros com vários significados; PAmh 134, 9 e outros papiros; 2 Mac; EpArist; Fílon, Leg. All. 3, 49; Jos., Ant. 16, 395; Justino.) Em nossa literatura, nas duas ocorrências, encontra-se também a variante de leitura <span class=\"greek\">ἐπισύστασις</span> (ver esse verbete).</p>\n<p class=\"entry-text\"><b>① Responsabilidade por uma questão: pressão, preocupação, cuidado.</b> Para <span class=\"greek\">ἡ</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">μοι</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">καθ</span>’ <span class=\"greek\">ἡμέραν</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.28\" target=\"_blank\" rel=\"noopener noreferrer\">2 Co 11:28</a>, é provável o sentido de <b>pressão, no sentido de ansiedade causada por intenso sentimento de responsabilidade</b>: <i>a pressão diária sobre mim</i>. Entre as alternativas figuram: <i>a atenção ou o cuidado diariamente exigido de mim</i> (<span class=\"greek\">ἐ</span>. = «atenção, cuidado»: Aristóteles, Phys. 196a, 38; Políbio 2, 2, 2; 11, 2, 4; Diod. S. 29, 32, final; EpArist 256; Just., D. 28, 1); <i>superintendência, supervisão</i> (Xen., Mem. 1, 5, 2, códices; ver ainda L-S-J-M, s.v. II 3), isto é, <i>o fardo da supervisão que pesa sobre mim dia após dia</i>; por fim, <span class=\"greek\">ἐ</span>. também pode significar <i>parada, impedimento, demora</i> (BGU 1832, 16; 1855, 19; Políbio 8, 28, 13), daí: <i>os impedimentos que me assediam diariamente</i>. Cf. o papel do <span class=\"greek\">ἐπιστάτης</span>, próximo verbete.</p>\n<p class=\"entry-text\"><b>② Ato de fazer alguma coisa parar: interrupção, parada.</b> (Xen., An. 2, 4, 26; Políbio 8, 28, 13.) <span class=\"greek\">ἐ</span>. <span class=\"greek\">ποιεῖν</span> <span class=\"greek\">ὄχλου</span>, <i>fazer formar-se uma multidão</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.12\" target=\"_blank\" rel=\"noopener noreferrer\">At 24:12</a>. A expressão indica pessoas que param, resultando na formação de uma aglomeração. Qualquer leitor ou ouvinte de Atos do século I provavelmente saberia que, se Paulo fosse responsável por reunir uma multidão ao seu redor, estaria em grave risco diante das autoridades romanas encarregadas da ordem pública. Portanto, a tradução «incitar uma multidão», adotada pela NRSV, avalia corretamente o sentido do texto (cf. 2 Mac 6:3, «investida», na NRSV). — DELG, s.v. <span class=\"greek\">ἵστημι</span>; M-M.</p></section></article>\n<article id=\"entry-epistates-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιστάτης, ου, ὁ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epistátēs⟧</span><span class=\"separator\">·</span><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Ver o verbete precedente; Homero e outros; frequentemente como termo técnico administrativo, usado para vários funcionários em literatura, inscrições, papiros, LXX; Jos., Ant. 8, 59; C. Ap. 2, 177.) Em Lucas, seis vezes no vocativo <span class=\"greek\">ἐπιστάτα</span>, como título dirigido a Jesus, quase sempre pelos discípulos (nos paralelos sinóticos, <span class=\"greek\">διδάσκαλε</span> [cf. Amônio, 100 d.C., p. 45 Valck., e Fílon, Poster. Cai. 54: <span class=\"greek\">ἐπ</span>. <span class=\"greek\">κ</span>. <span class=\"greek\">διδάσκαλοι</span>], <span class=\"greek\">κύριε</span>, <span class=\"greek\">ῥαββί</span>): <b>mestre.</b> (Cf. IG XII/1, 43, 21s.: <span class=\"greek\">ἐπιστάταν</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">παιδῶν</span>; IPriene 112, 73ss. [depois de 84 a.C.]: <span class=\"greek\">ἐ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">ἐφήβων</span>, cuja tarefa era <span class=\"greek\">τὰς</span> <span class=\"greek\">ψυχὰς</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">ἀρετὴν</span> <span class=\"greek\">προάγεσθαι</span>, <i>conduzir as almas à virtude</i>; Rouffiac, pp. 56s. — Diod. S. 3, 72, 1: Aristeu, preceptor de Dioniso; 3, 73, 4: Olimpo, preceptor de Zeus; 10, 3, 4: Ferécides, mestre de Pitágoras; todos chamados <span class=\"greek\">ἐπιστάτης</span>.) <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.5\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 5:5</a>; 8:24, 45; 9:33, 49; 17:13. — O. Glombitza, ZNW 49 (1958), pp. 275–278. — DELG, s.v. <span class=\"greek\">ἵστημι</span>; M-M; TW.</p></section></article>\n<article id=\"entry-epistello-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιστέλλω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epistéllō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Ver <span class=\"greek\">ἐπιστολή</span>, <span class=\"greek\">στέλλω</span>.) Primeiro aoristo <span class=\"greek\">ἐπέστειλα</span>; perfeito, segunda pessoa do singular, <span class=\"greek\">ἐπέστακλας</span>, 3 Km 5:22, códice A. <b>Enviar algo a alguém, informar ou instruir por carta; também simplesmente escrever.</b> (Assim Heródoto e outros; SIG 837, 14; papiros, LXX.) Com dativo de pessoa (PFay 133, 12; Jos., Ant. 4, 13; 14, 52): <span class=\"greek\">διὰ</span> <span class=\"greek\">βραχέων</span> <span class=\"greek\">ἐπέστειλα</span> <span class=\"greek\">ὑμῖν</span>, <i>escrevi-vos brevemente</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.22\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 13:22</a> (cf. Herm. Wr. 14, 1: <span class=\"greek\">σοι</span> <span class=\"greek\">δι</span>’ <span class=\"greek\">ὀλίγων</span> <span class=\"greek\">ἐ</span>.). <span class=\"greek\">ἱκανῶς</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">τινὶ</span> <span class=\"greek\">περί</span> <span class=\"greek\">τινος</span>, <i>[escrever] suficientemente a alguém acerca de alguma coisa</i>, 1 Cl 62:1 (cf. Ps.-Ésquines, Ep. 12, 14; Jos., Ant. 12, 50). <span class=\"greek\">περί</span> <span class=\"greek\">τινος</span>, <i>acerca de alguém</i> (cf. UPZ 110, 185 [164 a.C.]; Jos., Ant. 18, 300), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.25\" target=\"_blank\" rel=\"noopener noreferrer\">At 21:25</a>. <span class=\"greek\">τινὶ</span> <span class=\"greek\">περί</span> <span class=\"greek\">τινος</span> (BGU 1081, 5), 1 Cl 47:3. Seguido de infinitivo substantivado: <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἀπέχεσθαι</span>, <i>abster-se</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.20\" target=\"_blank\" rel=\"noopener noreferrer\">At 15:20</a>. Uso absoluto, 1 Cl 7:1. — M-M; TW.</p></section></article>\n<article id=\"entry-epistei-epistethi-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιστῇ, ἐπίστηθι</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epistêi, epístēthi⟧</span><span class=\"separator\">·</span><span>formas verbais; remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><b>Remissão:</b> <span class=\"greek\">ἐπιστῇ</span>, <span class=\"greek\">ἐπίστηθι</span>: ver <span class=\"greek\">ἐφίστημι</span>.</p></section></article>\n<article id=\"entry-episteme-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιστήμη, ης, ἡ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epistḗmē⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Ver <span class=\"greek\">ἐπίσταμαι</span>; Sófocles, Tucídides e posteriores; Epicteto; Vett. Val. 211, 18; Herm. Wr. 4, 6; 10, 9: <span class=\"greek\">ἐπιστήμη</span> <span class=\"greek\">δῶρον</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θεοῦ</span>, «conhecimento, dádiva de Deus»; PFay 106, 22; POxy 896, 5; LXX; En; PsSol 2:33; JosAs 4:9; AssMos, fragmento e; Fílon; Justino, Taciano, Atenágoras.) <b>Posse ou obtenção de conhecimento, com ênfase na compreensão dos aspectos daquilo que é aprendido: entendimento, conhecimento.</b> Com <span class=\"greek\">σοφία</span>, <span class=\"greek\">σύνεσις</span>, <span class=\"greek\">γνῶσις</span> (Eneias, o Tático, 580: <span class=\"greek\">μετὰ</span> <span class=\"greek\">ξυνέσεως</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἐ</span>.; Just., D. 3, 5: <span class=\"greek\">ἐ</span>. <span class=\"greek\">τίς</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">παρέχουσα</span> <span class=\"greek\">αὐτῶν</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀνθρωπίνων</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">θείων</span> <span class=\"greek\">γνῶσιν</span>), B 2:3; 21:5.</p>\n<p class=\"entry-text\">Como virtude cristã, Hv 3, 8, 5; 7 (cf. Cebes 20, 3. Quanto à relação entre <span class=\"greek\">πίστις</span> e <span class=\"greek\">ἐπιστήμη</span>, ver Simplício, comentário a Epicteto, p. 110, 35ss.: <span class=\"greek\">τὸ</span> <span class=\"greek\">ἀκοῦσαι</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">ὅτι</span> <span class=\"greek\">ἀθάνατός</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ψυχή</span>, <span class=\"greek\">πίστιν</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">ποιεῖ</span> <span class=\"greek\">βεβαίαν</span>, <span class=\"greek\">οὐ</span> <span class=\"greek\">μέντοι</span> <span class=\"greek\">ἐπιστήμην</span>. <span class=\"greek\">εἰ</span> <span class=\"greek\">δέ</span> <span class=\"greek\">τις</span> <span class=\"greek\">ἀξιοῦται</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">αἰτίας</span> <span class=\"greek\">μανθάνειν</span> … = <i>quando alguém ouve de Deus [pela mediação de um <span class=\"greek\">μάντις</span>] que a alma é imortal, isso produz, sem dúvida, uma fé firme, mas não conhecimento. Porém, quando alguém é considerado digno por Deus de aprender também as causas …</i> [então se manifesta <span class=\"greek\">ἐπιστήμη</span>]). <span class=\"greek\">ἔπαινος</span> <span class=\"greek\">ἐπιστήμης</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.4.8\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 4:8</a>, variante de leitura. — DELG, s.v. <span class=\"greek\">ἐπίσταμαι</span>; M-M; TW.</p></section></article>\n<article id=\"entry-epistemon-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιστήμων, ον</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epistḗmōn⟧</span><span class=\"separator\">·</span><span>adjetivo; genitivo -ονος</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Genitivo -<span class=\"greek\">ονος</span> (ver <span class=\"greek\">ἐπίσταμαι</span>; Homero e outros; Epicteto 2, 22, 3; POxy 1469, 12; LXX; En 5:8; Fílon; Just., D. 8, 5; Ath. 9:1: <span class=\"greek\">ἐπιστημονεστάτους</span>). <b>Que possui conhecimento capaz de torná-lo eficaz no exercício do que sabe: perito, instruído, entendido.</b> Com <span class=\"greek\">σοφός</span>, como em Dt 1:13; 4:6; Dn 5:11; Fílon, Migr. Abr. 58: <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 3:13</a>; o perito em <span class=\"greek\">σοφία</span> será reconhecido pela qualidade de sua atuação. B 6:10; com <span class=\"greek\">συνετός</span>, como em Dn 6:4: <span class=\"greek\">οἱ</span> <span class=\"greek\">ἐνώπιον</span> <span class=\"greek\">ἑαυτῶν</span> <span class=\"greek\">ἐ</span>., <i>aqueles que se consideram peritos segundo sua própria avaliação</i>, B 4:11 (Is 5:21). — DELG, s.v. <span class=\"greek\">ἐπίσταμαι</span> (bibliografia); M-M.</p></section></article>"};
